Source.BuildSpec:
{
  "version": "0.2",
  "env": {
    "shell": "bash",
    "exported-variables": [
      "INVENTORY_S3_URI"
    ]
  },
  "phases": {
    "build": {
      "commands": [
        "set -euo pipefail\nmkdir -p /tmp/scanner && cd /tmp/scanner\necho '' | base64 -d | tar -xJ\npython3 collect_inventory.py --yes --output /tmp/scanner/outputs 2>&1 | tee /tmp/scan.log\nZIP=$(sed -n 's/^RETURN_THIS_ZIP=//p' /tmp/scan.log | tail -n 1)\n[ -n \"$ZIP\" ] && [ -f \"$ZIP\" ] || { echo \"The scan did not produce a zip\"; exit 1; }\nKEY=\"$INVENTORY_PREFIX/$(basename \"$ZIP\")\"\naws s3 cp \"$ZIP\" \"s3://$INVENTORY_BUCKET/$KEY\" --acl bucket-owner-full-control --no-progress\nexport INVENTORY_S3_URI=\"s3://$INVENTORY_BUCKET/$KEY\"\necho \"INVENTORY_S3_URI=$INVENTORY_S3_URI\""
      ]
    }
  }
}
